function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*1299827+31);var wl=R()*2,wm=R();var cfgs=[];[2,4,6,8].forEach(function(l){[64,128,256].forEach(function(w){[2,4,8].forEach(function(h){var noise=R()*0.05;var c=(l*l*w/4096)*(1+wl)+(h/8)*(0.5+wm)+noise;cfgs.push({layers:l,width:w,heads:h,cost:+c.toFixed(4)});});});});cfgs.sort(function(a,b){return a.cost-b.cost;});var bc=cfgs.filter(function(c){return c.layers===8&&c.width===256&&c.heads===8;})[0].cost;var best=cfgs[0];return{configs_evaluated:cfgs.length,best:best,baseline_cost:+bc.toFixed(4),improvement_pct:+((bc-best.cost)/bc*100).toFixed(1)};}
var SEED = 86001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

